def get_icon(name: str, color: str = "#A6ABA8") -> QIcon:
    """Generates a QIcon from the SVG string with the specified color."""
    if name not in SVG_ICONS:
        return QIcon()
    
    svg_str = SVG_ICONS[name]
    # Replace stroke="currentColor" with the specific hex color
    svg_str = svg_str.replace('stroke="currentColor"', f'stroke="{color}"')
    
    renderer = QSvgRenderer(QByteArray(svg_str.encode('utf-8')))
    pixmap = QPixmap(32, 32)
    pixmap.fill(QColor("transparent"))
    painter = QPainter(pixmap)
    # Render with some padding
    renderer.render(painter)
    painter.end()
    
    return QIcon(pixmap)
